fn mark(kind: &str) -> &'static str {
    match kind {
        "codex" => CODEX,
        "claude" => CLAUDE,
        "hermes" => HERMES,
        "antigravity" => ANTIGRAVITY,
        "grok" => GROK,
        "pi" => PI,
        "opencode" => OPENCODE,
        "gemini" => GEMINI,
        "kiro" => KIRO,
        _ => "",
    }
}

#[component]
pub fn ProviderMark(kind: String) -> impl IntoView {
    view! { <span class="provider-mark" aria-hidden="true" inner_html=mark(&kind)></span> }
}
